27:     private static final String[][] LIVE_TV_HANDLERS = {
28:         {"com.android.tv", "com.android.tv.MainActivity"},
29:         {"com.droidlogic.android.tv", "com.android.tv.TvActivity"},
30:         {"com.mediatek.tv", "com.mediatek.tv.TvActivity"}
