33:     public static class HdmiInput {
34:         public final String id;
35:         public final String label;
36:         public final Uri passthroughUri;
37:         public final boolean isHidden;
38: 
39:         public HdmiInput(String id, String label, Uri passthroughUri, boolean isHidden) {
40:             this.id = id;
41:             this.label = label;
42:             this.passthroughUri = passthroughUri;
43:             this.isHidden = isHidden;
