47:     /**
48:      * Queries physical HDMI TV inputs, filters hidden inputs, sanitizes labels, and sorts deterministically.
49:      */
50:     public static List<HdmiInput> queryHdmiInputs(Context context, int maxInputs) {
51:         List<HdmiInput> result = new ArrayList<>();
52:         if (context == null) return result;
53:         TvInputManager tim = (TvInputManager) context.getSystemService(Context.TV_INPUT_SERVICE);
54:         if (tim == null) return result;
55: 
56:         List<TvInputInfo> inputs;
57:         try {
58:             inputs = tim.getTvInputList();
59:         } catch (Exception e) {
60:             return result;
61:         }
62:         if (inputs == null) return result;
63: 
64:         List<TvInputInfo> filtered = new ArrayList<>();
65:         for (TvInputInfo in : inputs) {
66:             if (in == null) continue;
67:             boolean isHdmi = in.getType() == TvInputInfo.TYPE_HDMI;
68:             boolean isPhysicalPort = in.getParentId() == null;
69:             boolean isHidden = false;
70:             try {
71:                 isHidden = in.isHidden(context);
72:             } catch (Throwable ignored) {}
73: 
74:             if (isHdmi && isPhysicalPort && !isHidden) {
75:                 filtered.add(in);
76:             }
77:         }
78: 
79:         Collections.sort(filtered, new Comparator<TvInputInfo>() {
80:             @Override
81:             public int compare(TvInputInfo a, TvInputInfo b) {
82:                 return a.getId().compareTo(b.getId());
83:             }
84:         });
85: 
86:         int count = Math.min(filtered.size(), maxInputs > 0 ? maxInputs : MAX_INPUTS_DEFAULT);
87:         for (int i = 0; i < count; i++) {
88:             TvInputInfo in = filtered.get(i);
89:             String rawLabel = resolveLabel(context, in, i + 1);
90:             String cleanLabel = VendorAdapter.sanitizeHdmiLabel(rawLabel);
91:             Uri uri = TvContract.buildChannelUriForPassthroughInput(in.getId());
92:             result.add(new HdmiInput(in.getId(), cleanLabel, uri, false));
93:         }
94: 
95:         return result;
96:     }
97: 
98:     private static String resolveLabel(Context context, TvInputInfo in, int indexFallback) {
99:         try {
100:             CharSequence custom = in.loadCustomLabel(context);
101:             if (custom != null && custom.length() > 0) {
102:                 return custom.toString();
103:             }
104:         } catch (Exception ignored) {}
105: 
106:         try {
107:             CharSequence label = in.loadLabel(context);
108:             if (label != null && label.length() > 0) {
109:                 return label.toString();
110:             }
111:         } catch (Exception ignored) {}
112: 
113:         return "HDMI " + indexFallback;
114:     }
115: 
116:     /**
117:      * Builds prioritized fallback dispatch chain for physical HDMI input:
118:      * 1. Google TV Input Player (if resolved default)
119:      * 2. Stock AOSP / OEM Live TV (com.android.tv, com.droidlogic.android.tv, com.mediatek.tv)
120:      * 3. Generic Action View on Passthrough URI
121:      */
122:     public static List<Intent> buildLaunchIntents(Context context, String inputId) {
123:         List<Intent> intents = new ArrayList<>();
124:         if (context == null || inputId == null || inputId.trim().isEmpty()) {
125:             return intents;
126:         }
127:         PackageManager pm = context.getPackageManager();
128:         Uri uri = TvContract.buildChannelUriForPassthroughInput(inputId);
129:         Intent baseView = new Intent(Intent.ACTION_VIEW, uri);
130: 
131:         // 1. Google TV Input Player
132:         try {
133:             ResolveInfo def = pm.resolveActivity(baseView, PackageManager.MATCH_DEFAULT_ONLY);
134:             if (def != null && def.activityInfo != null && INPUT_PLAYER.equals(def.activityInfo.packageName)) {
135:                 intents.add(new Intent(baseView).setClassName(INPUT_PLAYER, def.activityInfo.name));
136:             }
137:         } catch (Exception ignored) {}
138: 
139:         // 2. Known OEM Live TV Handlers (AOSP Live TV, Droidlogic, MediaTek)
140:         for (String[] target : LIVE_TV_HANDLERS) {
141:             Intent t = new Intent(baseView).setClassName(target[0], target[1]);
142:             try {
143:                 if (t.resolveActivity(pm) != null) {
144:                     intents.add(t);
145:                 }
146:             } catch (Exception ignored) {}
147:         }
148: 
149:         // 3. Generic Action View on Passthrough URI
150:         intents.add(baseView);
151:         return intents;
152:     }
153: 
154:     /**
155:      * Executes the launch sequence across the 5-tier fallback chain.
156:      */
157:     public static boolean launchInput(Context context, String inputId) {
158:         if (context == null) return false;
159:         if (inputId != null && !inputId.trim().isEmpty()) {
160:             List<Intent> tries = buildLaunchIntents(context, inputId);
161:             for (Intent intent : tries) {
162:                 intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
163:                 try {
164:                     context.startActivity(intent);
165:                     return true;
166:                 } catch (Exception ignored) {}
167:             }
168:         }
169: 
170:         // Fallback: hardware KEYCODE_TV_INPUT broadcast
171:         try {
172:             Intent keyIntent = new Intent(Intent.ACTION_MAIN);
173:             keyIntent.addCategory(Intent.CATEGORY_DEFAULT);
174:             keyIntent.putExtra(Intent.EXTRA_KEY_EVENT, new KeyEvent(KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_TV_INPUT));
175:             keyIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
176:             context.sendBroadcast(keyIntent);
177:             return true;
178:         } catch (Exception ignored) {}
179: 
180:         return false;
181:     }
182: }
