18: public class OledProtectionService {
19: 
20:     public static final long DEFAULT_INACTIVITY_TIMEOUT_MS = 180_000L; // 180s
21:     public static final long PIXEL_SHIFT_INTERVAL_MS = 60_000L;        // 60s
22:     public static final int PURE_BLACK_COLOR = 0xFF000000;             // #000000
23: 
24:     // Orbital micro-shift coordinates within [-2, +2] px bounds
25:     private static final int[][] SHIFT_ORBIT = {
26:         {0, 0}, {1, 0}, {2, 1}, {1, 2}, {0, 2}, {-1, 1}, {-2, 0}, {-1, -1}, {0, -2}, {1, -1}
27:     };
28: 
29:     private final Handler handler;
30:     private Activity activity;
31:     private View[] shiftViews;
32:     private long inactivityTimeoutMs = DEFAULT_INACTIVITY_TIMEOUT_MS;
33:     private boolean pixelShiftEnabled = true;
34:     private int shiftIndex = 0;
35:     private boolean isDimmed = false;
36: 
37:     public OledProtectionService() {
38:         Handler h = null;
39:         try {
40:             Looper looper = Looper.getMainLooper();
41:             if (looper != null) {
42:                 h = new Handler(looper);
43:             }
44:         } catch (Throwable ignored) {}
45:         this.handler = h;
46:     }
47: 
48:     private final Runnable inactivityRunnable = new Runnable() {
49:         @Override
50:         public void run() {
51:             triggerDaydreamOrDim();
52:         }
53:     };
54: 
55:     private final Runnable pixelShiftRunnable = new Runnable() {
56:         @Override
57:         public void run() {
58:             stepPixelShift();
59:             if (pixelShiftEnabled && handler != null) {
60:                 handler.postDelayed(this, PIXEL_SHIFT_INTERVAL_MS);
61:             }
62:         }
63:     };
64: 
65:     public void attach(Activity activity, View... shiftViews) {
66:         this.activity = activity;
67:         this.shiftViews = shiftViews;
68:         resetInactivityTimer();
69:         if (pixelShiftEnabled) {
70:             startPixelShift();
71:         }
72:     }
73: 
74:     public void detach() {
75:         stopInactivityTimer();
76:         stopPixelShift();
77:         restoreNormalState();
78:         this.activity = null;
79:         this.shiftViews = null;
80:     }
81: 
82:     public void configure(long timeoutSeconds, boolean pixelShift) {
83:         this.inactivityTimeoutMs = timeoutSeconds > 0 ? timeoutSeconds * 1000L : DEFAULT_INACTIVITY_TIMEOUT_MS;
84:         this.pixelShiftEnabled = pixelShift;
85:         resetInactivityTimer();
86:         if (pixelShiftEnabled) {
87:             startPixelShift();
88:         } else {
89:             stopPixelShift();
90:             resetShiftPositions();
91:         }
92:     }
93: 
94:     /**
95:      * Invoked on any remote D-pad or key event in MainActivity.
96:      */
97:     public void onUserInteraction() {
98:         if (isDimmed) {
99:             restoreNormalState();
100:         }
101:         resetInactivityTimer();
102:     }
103: 
104:     public void resetInactivityTimer() {
105:         if (handler != null) {
106:             handler.removeCallbacks(inactivityRunnable);
107:             handler.postDelayed(inactivityRunnable, inactivityTimeoutMs);
108:         }
109:     }
110: 
111:     public void stopInactivityTimer() {
112:         if (handler != null) {
113:             handler.removeCallbacks(inactivityRunnable);
114:         }
115:     }
116: 
117:     private void startPixelShift() {
118:         if (handler != null) {
119:             handler.removeCallbacks(pixelShiftRunnable);
120:             handler.postDelayed(pixelShiftRunnable, PIXEL_SHIFT_INTERVAL_MS);
121:         }
122:     }
123: 
124:     private void stopPixelShift() {
125:         if (handler != null) {
126:             handler.removeCallbacks(pixelShiftRunnable);
127:         }
128:     }
