130:     /**
131:      * Shifts registered static views by +/-1-2px along the orbital sequence.
132:      */
133:     public void stepPixelShift() {
134:         if (shiftViews == null || shiftViews.length == 0) return;
135:         shiftIndex = (shiftIndex + 1) % SHIFT_ORBIT.length;
136:         int dx = SHIFT_ORBIT[shiftIndex][0];
137:         int dy = SHIFT_ORBIT[shiftIndex][1];
138: 
139:         for (View view : shiftViews) {
140:             if (view != null) {
141:                 view.setTranslationX(dx);
142:                 view.setTranslationY(dy);
143:             }
144:         }
145:     }
146: 
147:     private void resetShiftPositions() {
148:         if (shiftViews == null) return;
149:         for (View view : shiftViews) {
150:             if (view != null) {
151:                 view.setTranslationX(0f);
152:                 view.setTranslationY(0f);
153:             }
154:         }
155:     }
