161:         if (activity == null || activity.isFinishing()) return;
162: 
163:         // Try standard Daydream Somnambulator
164:         Intent dream = new Intent(Intent.ACTION_MAIN)
165:                 .setClassName("com.android.systemui", "com.android.systemui.Somnambulator")
166:                 .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
167:         try {
168:             activity.startActivity(dream);
169:             return;
170:         } catch (Exception ignored) {}
171: 
172:         // Fallback: Dim the window
173:         try {
174:             WindowManager.LayoutParams lp = activity.getWindow().getAttributes();
175:             lp.screenBrightness = 0.05f;
176:             activity.getWindow().setAttributes(lp);
177:             isDimmed = true;
178:         } catch (Exception ignored) {}
179:     }
180: 
181:     private void restoreNormalState() {
182:         if (activity == null || !isDimmed) return;
183:         try {
184:             WindowManager.LayoutParams lp = activity.getWindow().getAttributes();
185:             lp.screenBrightness = WindowManager.LayoutParams.BRIGHTNESS_OVERRIDE_NONE;
186:             activity.getWindow().setAttributes(lp);
187:             isDimmed = false;
188:         } catch (Exception ignored) {}
189:     }
