193:         String display = "";
194:         try {
195:             if (Build.MODEL != null) model = Build.MODEL.toUpperCase();
196:             if (Build.DISPLAY != null) display = Build.DISPLAY.toUpperCase();
197:         } catch (Throwable ignored) {}
198:         return model.contains("OLED") || display.contains("OLED")
199:                 || model.contains("A80") || model.contains("A90") || model.contains("A95");
200:     }
201: }
